import {createPoseBuffer} from './pose-buffer.js';
import {snowRadius} from './aurora-terrain.js';
import * as T from './vendor/three.module.js';
import {createTeddy} from './teddy.js';
export function createAuroraPublic({world,interior,player,pose,wildlife}){
 let session=null,busy=false,joined=false,stopped=false,guests=[],self=null,spawned=false;const peers=new Map();
 async function api(body){const r=await fetch('/api/aurora/lodge',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf,'X-Planet-Space':String(session.space)},body:JSON.stringify(body),keepalive:body.action==='leave',signal:AbortSignal.timeout(12000)});const v=await r.json();if(!r.ok){const error=Error(v.error||'暂时连接不到雪境');error.status=r.status;throw error};return v;}
 function paint(value){self=value.self;guests=value.guests||[];const own=guests.find(g=>g.id===self);interior.setOrder(own);
 if(own&&!spawned){spawned=true;if(own.appearance){player.design(own.appearance);player.outfit(own.outfit||'plain');interior.setAppearance(own.appearance,own.outfit)}const phi=(Number(own.id)||1)*2.39996,theta=.30,normal=new T.Vector3(Math.sin(theta)*Math.cos(phi),Math.cos(theta),Math.sin(theta)*Math.sin(phi));world.add(player.avatar);player.avatar.position.copy(normal).multiplyScalar(snowRadius(theta,phi)+.018);player.avatar.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),normal);player.seatTick(false,.1);player.legs.forEach(g=>g.rotation.x=0);}
 const live=new Set();for(const g of guests){if(g.id===self||!g.position||!g.quaternion)continue;live.add(g.id);let peer=peers.get(g.id);if(!peer){peer=createTeddy(world,g.avatar);peer.avatar.scale.setScalar(.63);if(g.appearance){peer.design(g.appearance);peer.outfit(g.outfit||'plain')}peers.set(g.id,peer)}peer.buffer??=createPoseBuffer();peer.buffer.push(g,performance.now(),g.room+':'+!!g.vehicle);}for(const [id,p] of peers)if(!live.has(id)){p.avatar.removeFromParent();p.vehicle?.dispose();peers.delete(id)}const count=document.querySelector('#aurora-count');if(count)count.textContent=guests.length+' 位访客';}
 async function sync(){if(!joined||busy||stopped||document.hidden)return;busy=true;try{paint(await api({action:'sync',...pose()}));}catch(e){if(e.status===409){try{paint(await api({action:'join',room:pose().room}));}catch{}}else console.warn('雪境连接暂时中断');}finally{busy=false}}
 const ready=(async()=>{let r;try{r=await fetch('/api/session',{credentials:'same-origin'});session=await r.json()}catch{session=null}if(!session?.authenticated){session=null;if(new URLSearchParams(location.search).has('embedded')&&window.parent!==window&&window.parent.PLANET_RUNTIME?.mode==='cloud')throw Error('请先登录再进入雪境');return;}paint(await api({action:'join',room:'outside'}));joined=true;player.setIdentity(session.avatars?.[session.actor]||0);interior.setIdentity(session.avatars?.[session.actor]||0);await sync();})();
 const timer=setInterval(sync,250);
 return {ready,sync,tick(dt,inside){for(const peer of peers.values()){const g=peer.buffer.sample();if(!g)continue;const parent=g.room==='inside'?interior.group:world;if(peer.avatar.parent!==parent)parent.add(peer.avatar);peer.avatar.visible=(g.room==='inside')===inside;peer.avatar.scale.setScalar(g.room==='inside'?.75:.63);peer.avatar.position.fromArray(g.position);peer.avatar.quaternion.fromArray(g.quaternion);peer.seatTick(g.seated,dt);if(g.animation){peer.body.position.fromArray(g.animation.bodyPosition);peer.body.rotation.fromArray([...g.animation.bodyRotation,'XYZ']);for(const key of ['arms','legs'])peer[key].forEach((a,i)=>a.rotation.fromArray([...g.animation[key][i],'XYZ']));peer.sipping(g.animation.drinking&&peer.arms[0].rotation.x<-1.1);if(g.animation.drinking){if(!peer.drink){peer.drink=new T.Mesh(new T.CylinderGeometry(.09,.075,.20,20,1,true),new T.MeshPhysicalMaterial({color:0xb8e5f2,roughness:.18,transparent:true,opacity:.65}));peer.arms[0].add(peer.drink);peer.drink.position.set(0,-.29,.10);}peer.drink.visible=true;}else if(peer.drink)peer.drink.visible=false;}if(g.vehicle){peer.vehicle??=wildlife.makeRemoteSleigh();if(peer.vehicle){peer.vehicle.mount.visible=!inside;peer.vehicle.mount.position.fromArray(g.vehicle.position);peer.vehicle.mount.quaternion.fromArray(g.vehicle.quaternion);peer.vehicle.body.rotation.fromArray([...g.vehicle.rotation,'XYZ']);peer.vehicle.tick(dt,g.vehicle.speed);}}else if(peer.vehicle){peer.vehicle.dispose();peer.vehicle=null;}}},state:()=>({joined,self,visitors:guests.length}),async stop(){stopped=true;clearInterval(timer);if(joined)try{await api({action:'leave'})}catch{}for(const p of peers.values()){p.avatar.removeFromParent();p.vehicle?.dispose();}peers.clear()},peers};
}
